require_once __DIR__.'/inc/site.php';begin_page('Flotsam : cache disque, mémoire et cache négatif','Flotsam: disk, memory and negative caches','Dossier pratique fondé sur le code OpenSimulator 0.9.3.1 : identifier, configurer et diagnostiquer les caches.','Practical guide based on OpenSimulator 0.9.3.1 source: identify, configure and diagnose caches.');
callout('Vérifiez le module actif et la configuration chargée avant toute commande. Un cache peut être nettoyé, mais un stockage persistant comme FSAssets ne doit jamais être supprimé comme un cache.','Check the active module and loaded settings before commands. Caches may be cleared, but permanent stores like FSAssets must never be deleted as if they were caches.');
echo '<nav class="install-toc"><strong>'.e(t('Dans ce chapitre','In this chapter')).'</strong><ul>';
